import {architectureProgram,illuminationGraphic} from './mission-architecture.js';
import {architectureTradeGraphic,structuralBounds,structuralBoundsGraphic,deploymentInterfacesFor} from './architecture-trades.js';
import {renderEnergySingleLine,renderThermalPath} from './energy-system.js';
import {renderComputeFabric,renderEarthServiceRoute} from './service-architecture.js';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f=(v,d=1)=>Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d}):'Unassessed';
const table=(heads,rows)=>'<div class="mb-table-scroll"><table><thead><tr>'+heads.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((x,i)=>'<'+(i?'td':'th scope="row"')+'>'+x+'</'+(i?'td':'th')+'>').join('')+'</tr>').join('')+'</tbody></table></div>';

export function architectureProgramRecord(h,s=null){
 const p=architectureProgram(h);
 p.deploymentInterfaces=deploymentInterfacesFor(h);
 p.graphics=[
  {id:'seasonal-illumination',title:'Orbit and illumination',product:'AP-01',svg:illuminationGraphic(h)},
  {id:'matched-architecture-trade',title:h.input.architectureFamily==='protected-core'?'Legacy matched architecture comparison':'Installed family and physical connections',product:'AP-02',svg:architectureTradeGraphic(h)},
  {id:'electrical-single-line',title:'Power interfaces and installed ratings',product:'AP-03',svg:renderEnergySingleLine(h,s)},
  {id:'thermal-transport',title:'Heat transport and cold control',product:'AP-03',svg:renderThermalPath(h,s)},
  {id:'compute-fabric',title:'Compute, storage and onboard fabric',product:'AP-04',svg:renderComputeFabric(h)},
  {id:'earth-service-route',title:'Spacecraft-to-customer service path',product:'AP-04',svg:renderEarthServiceRoute(h,s||{})},
  {id:'structural-control-bounds',title:'Structure, mechanisms and pointing',product:'AP-05',svg:structuralBoundsGraphic(structuralBounds(h))}
 ];
 return p;
}

export function renderArchitectureProgram(record){
 const p=record.architectureProgram||record,d=p.selectedCase,a=p.applicability,e=p.energy,s=p.service;
 const thermalLabel=({'passive-local':'Passive local transport','redundant-pumped':'Independent pumping loops','heat-lift':'Powered heat lift',pumped:'Allocated pumped transport'})[p.physicalArchitecture?.topology?.thermalTopology]||'Allocated thermal transport';
 const rangeText=x=>f(x.minimum)+'–'+f(x.maximum)+' '+esc(x.unit);
 const limits=(a?.checks||[]).map(x=>[esc(x.label),f(x.actual)+' '+esc(x.unit),rangeText(x),'<span class="mb-badge" data-tone="'+(x.status==='inside'?'adopt':'review')+'">'+esc(x.status==='inside'?'Within study range':x.status==='outside'?'Outside study range':'Unassessed')+'</span><small>'+esc(x.basis)+'</small>']);
 const figures=p.graphics||[];
 return '<section class="mb-section mb-architecture-program"><p class="mb-kicker">'+esc(p.revision)+' · '+esc(p.identity.vehicleId)+'</p><h2>Architecture and engineering interfaces</h2><p>'+esc(p.scope)+'</p>'
 +'<div class="mb-callout"><strong>Selected architecture · '+esc(p.reference.architectureLabel||p.reference.physicalTopology)+'</strong><p>'+esc(p.trade?.decision||p.reference.physicalTopology)+'</p><p>'+esc(p.reference.boundary)+'</p></div>'
 +'<div class="mb-summary"><div><small>'+esc(p.missionCase?.label||'Selected mission')+'</small><strong>'+f(d.altitudeKm,0)+' km · '+f(d.inclinationDeg)+'° · '+f(d.missionYears)+' years</strong><span>'+esc(d.epoch)+' · RAAN '+f(d.raanDeg)+'°</span></div><div><small>Current study applicability</small><strong>'+esc(a?.label||'Unassessed')+'</strong><span>Numerical capability and qualification are assessed separately</span></div><div><small>Selected electrical interfaces</small><strong>'+f(e.electrical.family.primaryV,0)+' / 48 / 28 V</strong><span>'+f(e.electrical.installedElectronicsKW,2)+' kW installed electronics · '+f(e.electrical.mppt.inputCapacityKW,0)+' kW MPPT input capacity</span></div><div><small>Cooling architecture</small><strong>'+esc(thermalLabel)+'</strong><span>'+esc(p.reference.thermalRedundancy)+'</span></div></div>'
 +'<details class="mb-disclosure"><summary>Legacy comparison and current installed configuration</summary>'+table(['Parameter','Retained legacy comparison','Current installed family'],[
  ['Mission','Live text service',esc(d.aiPurpose)],['Orbit','550 km · 53° · circular',f(d.altitudeKm,0)+' km · '+f(d.inclinationDeg)+'° · e = '+f(d.ecc,4)],['Life','5 years',f(d.missionYears)+' years'],['Compute','12 repeated trays',f(d.trayCount,0)+' trays · '+f(e.electrical.installedElectronicsKW,2)+' kW installed'],['Solar / radiator planform','190 / 65 m²',f(d.solarM2)+' / '+f(d.radiatorM2)+' m²'],['Battery / propellant','40 kWh / 450 kg',f(d.batteryKWh)+' kWh / '+f(d.propellantKg)+' kg']
 ])+'<p class="mb-muted">This historical comparison retains the original protected-core study. It does not replace the selected family or its source/common mission case, and it does not qualify either design.</p></details>'
 +'<section class="mb-section"><h3>Engineering interface drawings</h3><p>The drawings use this installed family, moving payload placement, thermal connections and mission. Alternative mass deltas remain unassessed when the legacy protected-core trade does not apply.</p><nav class="mb-figure-index" aria-label="Architecture drawings">'+figures.map(g=>'<a href="#mb-figure-'+esc(g.id)+'">'+esc(g.title)+'</a>').join('')+'</nav><div class="mb-interface-figures">'+figures.map(g=>'<figure id="mb-figure-'+esc(g.id)+'"><figcaption><span>'+esc(g.product)+'</span> '+esc(g.title)+'</figcaption><div class="mb-svg-scroll">'+g.svg+'</div></figure>').join('')+'</div></section>'
 +'<details class="mb-disclosure"><summary>Six connected designs · decisions and verification gates</summary><p>Each work product records the selected design, its implemented analysis and the evidence needed at the next gate. The public comparisons inform the decisions; project allocations remain identified as such.</p>'+p.workProducts.map(w=>'<article class="mb-evidence"><header><div><p class="mb-kicker">'+esc(w.id)+' · '+esc(w.owner)+'</p><h3>'+esc(w.title)+'</h3></div><span class="mb-badge" data-tone="adopt">Preliminary design implemented</span></header><p>'+esc(w.decision)+'</p><p><b>Available now.</b> '+esc(w.implemented)+'</p><details><summary>Remaining evidence and acceptance gate</summary><p>'+esc(w.evidence)+'</p><p><b>Method.</b> '+esc(w.method)+' · <b>Gate.</b> '+esc(w.gate)+'</p></details></article>').join('')+'</details>'
 +'<details class="mb-disclosure"><summary>Commissioning interfaces and gates</summary><p>Required handoffs and verification products for the selected deployment sequence.</p>'+table(['Stage','Authority','Gate','Evidence'],(p.deploymentInterfaces||[]).map(row=>[esc(row.step),esc(row.authority),esc(row.gate),esc(row.product)]))+'</details>'
 +'<section class="mb-section"><h3>Supported study range</h3><p>'+esc(a?.meaning||p.evidenceStatus)+'</p>'+table(['Boundary','Current value','Study allocation','Applicability'],limits)+'<p class="mb-muted">Power conversion, hydraulic flow, fabric ports, storage and terminal rates also impose explicit numerical capacities in their domain assessments. Changing an orbit or service request cannot increase those installed capacities.</p></section>'
 +'<section class="mb-section"><h3>Data custody and availability</h3><p>'+esc(s.data?.checkpointPolicy||s.data?.custodyPolicy||'Training reserves two alternating local checkpoint slots: the last complete checkpoint remains resident until its successor commits. A separate product spool retains the chosen final artifact until delivery. Local restart state and Earth delivery have different custody responsibilities.')+'</p><p>'+esc(s.fabric.singlePointDisposition)+'</p><p>'+esc(s.route.usesRelay?'Relay provider, protocol compatibility and service allocation remain unassessed. Installed terminal caps and acquisition time are enforced.':'The selected direct ground route uses station visibility, acquisition and link-budget capacity. Ground service allocation and any optical-weather availability remain evidence items.')+'</p></section>'
 +'<details class="mb-disclosure"><summary>Architecture gap implementation register · '+p.gaps.length+' items</summary>'+table(['Gap','Implemented work product','Affected domains','Status'],p.gaps.map(g=>[esc(g.id+' · '+g.title),esc(g.product),g.domains.map(esc).join(', '),esc(g.status)]))+'</details>'
 +'<section class="mb-section"><h3>Public design comparisons</h3><p>Reference figures retain their original configuration, date and resource boundary. They are not substituted for ODC flight requirements or equipment evidence.</p>'+p.sources.map(r=>'<article class="mb-source"><div><span class="mb-rule-id">'+esc(r.id)+'</span><h4><a href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer">'+esc(r.name)+' ↗</a></h4></div><small>'+esc(r.date)+'</small><p>'+esc(r.basis)+'</p><p><b>Design lesson.</b> '+esc(r.lesson)+'</p><p class="mb-muted">'+esc(r.boundary)+'</p></article>').join('')+'</section></section>';
}

export function architectureProgramHtml(record){
 const p=record.architectureProgram||record;
 return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ODC architecture and interfaces</title><style>body{font:15px/1.55 system-ui;color:#182b35;max-width:1100px;margin:30px auto;padding:0 24px}h1,h2,h3{line-height:1.25}h2{font-size:28px}h3{font-size:21px}a{color:#165d67}small{display:block;color:#52616b}p{margin:8px 0}.mb-section{margin:28px 0}.mb-summary{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:18px 0}.mb-summary>div,.mb-callout{background:#eef3f3;padding:14px}.mb-summary strong,.mb-summary span{display:block}.mb-evidence,.mb-source{border-top:1px solid #ccd8dc;padding:16px 0}.mb-badge{display:inline-block;border:1px solid #a6bbbd;padding:3px 7px;border-radius:4px;font-size:12px}.mb-kicker{font-size:12px;letter-spacing:.06em}.mb-muted{color:#52616b}figure{margin:24px 0;break-inside:avoid}figcaption{font-weight:650;margin-bottom:8px}svg{width:100%;height:auto;display:block}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;vertical-align:top;border-bottom:1px solid #ccd8dc;padding:9px}th:first-child{width:24%}details{margin:18px 0}summary{font-weight:650}@media(max-width:640px){.mb-summary{grid-template-columns:1fr}.mb-table-scroll,.mb-svg-scroll{overflow:auto}svg{min-width:650px}}@media print{details>*{display:block!important}tr{break-inside:avoid}body{font-size:10pt}h3,figcaption{break-after:avoid}}</style><h1>Orbital Data Center · Architecture and interfaces</h1>'+renderArchitectureProgram(p).replaceAll('<details','<details open')+'<script type="application/json" id="architecture-program-record">'+JSON.stringify(p).replaceAll('<','\\u003c')+'</script></html>';
}
